package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A sheet's rate for a grade: a percent with two decimals, in force from its from-date (none: from
 * the beginning of time) until the grade's next rate, or through its to-date when it has one. Its
 * version counts how many times it has been set: the older ones are kept as {@link RateVersion}s.
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    @Column(name = "version", nullable = false)
    private int version = 1;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate fromDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public void setToDate(LocalDate toDate) {
        this.toDate = toDate;
    }

    /** Whether the rate is still in force on a date: it has no to-date, or the date is on or before it. */
    public boolean runsThrough(LocalDate date) {
        return toDate == null || !date.isAfter(toDate);
    }

    /** How many versions the rate has had: 1 when first set, one more each time it is set again. */
    public int getVersion() {
        return version;
    }

    public void setVersion(int version) {
        this.version = version;
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.sheet.AsOfFilter;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The rates a sheet works out what is due from: its own, then its parent's, then the parent's parent,
 * up to {@link #LEVELS} levels up. A grade with no rate in force on a date on a sheet takes the
 * rate in force for it on that date on the nearest ancestor that has one.
 */
@Service
public class RateChain {

    /** How many levels up a sheet's ancestors' rates are looked for. */
    public static final int LEVELS = 3;

    private final SheetRepository sheets;
    private final RateRepository rates;
    private final RateLogRepository rateLog;

    public RateChain(SheetRepository sheets, RateRepository rates, RateLogRepository rateLog) {
        this.sheets = sheets;
        this.rates = rates;
        this.rateLog = rateLog;
    }

    /** The sheet's id, then its parent's, and so on, up to {@link #LEVELS} levels up. */
    public List<String> lineage(String sheetId) {
        List<String> ids = new ArrayList<>();
        ids.add(sheetId);
        String at = sheetId;
        while (ids.size() <= LEVELS) {
            String parent = sheets.findById(at).map(Sheet::getParentId).orElse(null);
            if (parent == null || ids.contains(parent)) {
                break;
            }
            ids.add(parent);
            at = parent;
        }
        return ids;
    }

    /** Whether naming {@code parentId} as the sheet's parent would make the sheet its own ancestor. */
    public boolean wouldLoop(String sheetId, String parentId) {
        List<String> seen = new ArrayList<>();
        String at = parentId;
        while (at != null && !seen.contains(at)) {
            if (at.equals(sheetId)) {
                return true;
            }
            seen.add(at);
            at = sheets.findById(at).map(Sheet::getParentId).orElse(null);
        }
        return false;
    }

    /**
     * The rates of the sheet and of each ancestor, nearest first, as the store holds them now. When the
     * request is answered as of a date, only the sheet is restored as it stood then (see {@link AsOfFilter}),
     * so each ancestor's rates are those it had at the end of that date.
     */
    public List<List<Rate>> current(String sheetId) {
        Optional<LocalDate> asOf = AsOfFilter.current();
        List<String> ids = lineage(sheetId);
        List<List<Rate>> chain = new ArrayList<>();
        chain.add(rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId));
        for (String id : ids.subList(1, ids.size())) {
            chain.add(asOf.isPresent() ? rateLog.asOf(id, asOf.get()) : rates.findBySheetIdOrderByGradeAscFromDateAsc(id));
        }
        return chain;
    }

    /** The rates of the sheet and of each ancestor, nearest first, as they stood at the end of a day. */
    public List<List<Rate>> asOf(String sheetId, LocalDate day) {
        return lineage(sheetId).stream().map(id -> rateLog.asOf(id, day)).toList();
    }

    /**
     * The grade's rate in force on a date: the sheet's own (as {@link RateRepository#inForce} picks it),
     * else the nearest ancestor's; empty when none has one.
     */
    public static Optional<Rate> inForce(List<List<Rate>> chain, String grade, LocalDate date) {
        for (List<Rate> level : chain) {
            Optional<Rate> rate = RateRepository.inForce(level, grade, date);
            if (rate.isPresent()) {
                return rate;
            }
        }
        return Optional.empty();
    }

    /** The grade's rate in force on a date on the sheet or, failing that, its nearest ancestor. */
    public Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return inForce(current(sheetId), grade, date);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's rates for each grade: set (or set again) on the screen, one per grade and from-date;
 * setting a grade's rate for a from-date it already has keeps the rate it replaces as an older
 * version and makes the new value (and its to-date) the newest, the one in force. A to-date before
 * the from-date is refused.
 */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository rateLog;
    private final RateVersionRepository versions;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final RoleService roles;
    private final RateChain chain;

    public RateService(RateRepository rates, RateLogRepository rateLog, RateVersionRepository versions,
            SheetService sheets, Audit audit,
            RollupService rollup, RoleService roles, RateChain chain) {
        this.chain = chain;
        this.rateLog = rateLog;
        this.versions = versions;
        this.roles = roles;
        this.rollup = rollup;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's own rates, then those of each of its ancestors, nearest first (see {@link RateChain}). */
    @Transactional(readOnly = true)
    public List<List<Rate>> list(String sheetId) {
        return chain.current(sheetId);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate,
            BigDecimal pct) {
        roles.refuseViewer(sheetId, user);
        if (toDate != null && fromDate != null && toDate.isBefore(fromDate)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Optional<Rate> replaced = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, fromDate);
        replaced.ifPresent(old -> {
            versions.save(new RateVersion(old));
            old.setVersion(old.getVersion() + 1);
        });
        Rate rate = replaced.orElseGet(() -> new Rate(sheetId, grade, fromDate, pct));
        rate.setPct(pct);
        rate.setToDate(toDate);
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException e) {
            // another user set this grade's rate from this date at the same moment
            throw new ResponseStatusException(HttpStatus.CONFLICT, "This rate was just set by someone else.");
        }
        rateLog.saveAndFlush(new RateLog(saved, sheets.today(sheetId)));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade + " rate="
                + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (fromDate != null ? " from=" + fromDate : "") + (toDate != null ? " to=" + toDate : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
