package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** A sheet's rates by grade, then by from-date. */
    List<Rate> findBySheetIdOrderByGradeAscFromDateAsc(String sheetId);

    /** A grade's rates on a sheet. */
    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** The grade's rate from a from-date, or its undated rate when the from-date is null. */
    default Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate fromDate) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> Objects.equals(r.getFromDate(), fromDate)).findFirst();
    }

    /**
     * The grade's rate in force on a date: the one with the latest from-date on or before it, an
     * undated rate counting as from the beginning of time; empty when none applies yet, or when that
     * one's to-date has passed by the date.
     */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return inForce(findBySheetIdAndGrade(sheetId, grade), grade, date);
    }

    /** The grade's rate in force on a date among the given rates, as {@link #findInForce} picks it. */
    static Optional<Rate> inForce(List<Rate> rates, String grade, LocalDate date) {
        return rates.stream().filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max((a, b) -> a.getFromDate() == null ? -1 : b.getFromDate() == null ? 1
                        : a.getFromDate().compareTo(b.getFromDate()))
                .filter(r -> r.runsThrough(date));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * One rate as it was set: the grade, its from-date and to-date, the percent, and the sheet's today
 * when it was set (none: from the beginning of time). Kept so the rates can be rebuilt as they stood
 * at the end of a day.
 */
@Entity
@Table(name = "rate_log")
public class RateLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    @Column(name = "made_on")
    private LocalDate madeOn;

    protected RateLog() {
    }

    public RateLog(Rate rate, LocalDate madeOn) {
        this.sheetId = rate.getSheetId();
        this.grade = rate.getGrade();
        this.fromDate = rate.getFromDate();
        this.toDate = rate.getToDate();
        this.pct = rate.getPct();
        this.madeOn = madeOn;
    }

    public Long getId() {
        return id;
    }

    /** Whether it was set by the end of a day: the sheet's today then on or before it. */
    public boolean madeBy(LocalDate day) {
        return madeOn == null || !madeOn.isAfter(day);
    }

    /** The rate as it was set, not to be saved. */
    public Rate toRate() {
        Rate rate = new Rate(sheetId, grade, fromDate, pct);
        rate.setToDate(toDate);
        return rate;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateLogRepository extends JpaRepository<RateLog, Long> {

    /** A sheet's rates as set, oldest first. */
    List<RateLog> findBySheetIdOrderByIdAsc(String sheetId);

    /**
     * The sheet's rates as they stood at the end of a day: each set while the sheet's today was on
     * or before it, a later one for the same grade and from-date replacing an earlier as its newest
     * version. Not to be saved.
     */
    default List<Rate> asOf(String sheetId, LocalDate day) {
        Map<List<Object>, Rate> by = new LinkedHashMap<>();
        for (RateLog set : findBySheetIdOrderByIdAsc(sheetId)) {
            if (set.madeBy(day)) {
                Rate rate = set.toRate();
                Rate older = by.get(Arrays.asList(set.getGrade(), set.getFromDate()));
                rate.setVersion(older == null ? 1 : older.getVersion() + 1);
                by.put(Arrays.asList(set.getGrade(), set.getFromDate()), rate);
            }
        }
        return new ArrayList<>(by.values());
    }
}
